// 나쁨: 나중에 못 찾는다
console.log(data);

// 좋음: 유니크한 표시 + 무엇인지
console.log('[cart-a4f2] 합계 계산 전', { items, coupon });
// -> 지울 때 'cart-a4f2' 로 한 번에 검색해 지운다

// 객체는 펼쳐진 상태로 보고 싶을 때
console.dir(el);          // DOM 요소를 객체로 본다
console.log(structuredClone(state));   // 나중에 바뀔 객체의 그 순간 사진

performance.mark('render:start');
renderList(rows);
performance.mark('render:end');
performance.measure('render', 'render:start', 'render:end');

// Performance 패널의 Timings 트랙에 이름이 그대로 보인다
// React·Vue 등은 자체 프로파일러가 비슷한 것을 해 준다

debugger;                    // 개발자도구가 열려 있으면 여기서 멈춘다

console.trace('여기까지 어떻게 왔나');   // 호출 스택만 찍기

// 특정 함수가 불릴 때마다 로그 (크롬 콘솔 전용)
monitor(myFunction);
unmonitor(myFunction);

// 이벤트가 발생할 때마다 로그
monitorEvents(document.body, 'click');

// 지금 무엇이 저장돼 있나
Object.entries(localStorage).forEach(([k, v]) => console.log(k, v.slice(0, 80)));

// 쿠키는 문서에서 보이는 것만 (HttpOnly 는 안 보인다 — Application 패널에서 확인)
document.cookie.split('; ').forEach((c) => console.log(c));

// 저장소 사용량
navigator.storage.estimate().then(console.log);
